CREATE TABLE public.background_job_state (job_name text PRIMARY KEY, status text NOT NULL DEFAULT 'idle' CHECK (status IN ('idle','running','paused','failed')), lease_expires_at timestamptz, paused_reason text, consecutive_rate_limits integer NOT NULL DEFAULT 0, last_started_at timestamptz, last_finished_at timestamptz, last_result jsonb, updated_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE public.background_job_state ENABLE ROW LEVEL SECURITY; GRANT ALL ON public.background_job_state TO service_role; CREATE POLICY "Service role manages background job state" ON public.background_job_state FOR ALL TO service_role USING (true) WITH CHECK (true); CREATE OR REPLACE FUNCTION public.claim_background_job(_job_name text, _lease_seconds integer DEFAULT 120) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE claimed boolean; BEGIN INSERT INTO public.background_job_state(job_name) VALUES(_job_name) ON CONFLICT(job_name) DO NOTHING; UPDATE public.background_job_state SET status='running',lease_expires_at=now()+make_interval(secs=>greatest(30,least(_lease_seconds,600))),last_started_at=now(),updated_at=now() WHERE job_name=_job_name AND status<>'paused' AND(status<>'running' OR lease_expires_at IS NULL OR lease_expires_at<=now()); GET DIAGNOSTICS claimed=ROW_COUNT; RETURN claimed; END $$; CREATE OR REPLACE FUNCTION public.finish_background_job(_job_name text,_status text,_result jsonb DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.background_job_state SET status=CASE WHEN _status IN('idle','paused','failed') THEN _status ELSE 'failed' END,lease_expires_at=NULL,last_finished_at=now(),last_result=_result,updated_at=now() WHERE job_name=_job_name; END $$; REVOKE ALL ON FUNCTION public.claim_background_job(text,integer) FROM PUBLIC,anon,authenticated; REVOKE ALL ON FUNCTION public.finish_background_job(text,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_background_job(text,integer) TO service_role; GRANT EXECUTE ON FUNCTION public.finish_background_job(text,text,jsonb) TO service_role;